basicCode.vanilla:
import { createComposerVoice } from '@/components/ui/composer-voice';

const voz = createComposerVoice({
  labels: rotulos,
  state: estado,
  onToggle: (intent) => (intent === 'start' ? comecar() : parar()),
});

createComposer({ labels, railStart: [voz] });

