withLevelCode.web:
// O componente NÃO capta áudio. Pedir permissão, captar, transcrever e o que
// fazer com o texto é de quem consome; aqui só se desenha o estado que chega.

// O nível é DECORATIVO: um número de 0 a 1 que desenha o som e não se anuncia.
{ state: 'recording', level: 0.62, elapsed: '0:12' }

// Já parou de captar e ainda processa. O alternador fica desabilitado, e o
// motivo vai no texto de estado — nunca só no cinza do botão.
{ state: 'transcribing', elapsed: '0:34' }

extensibilityCode.web:
// O componente desenha o que RECEBE, e não sabe de onde o som vem.
// Permissão, captura, transcrição e o destino do texto são de quem consome.
{
  state: 'recording',  // em que ponto o ditado está
  level: 0.62,         // o som que entra, de 0 a 1 — desenho, e só
  elapsed: '0:12',     // já escrito: formato de duração é decisão de idioma
  disabled: false,     // ditar não está disponível agora
}

// O pedido chega como intenção, e não como estado novo: entre pedir para
// começar e estar captando existe uma permissão que só quem consome resolve.
onToggle: (intent) => (intent === 'start' ? comecar() : parar());

customizationCode.web:
.nds-composer-voice-status {
  min-inline-size: 8ch;
}

/* O nível é valor de RUNTIME, e por isso entra por custom property em vez de
   um `style` de desenho — que sairia do tema, da densidade e da escala
   tipográfica junto. Sem nível declarado, a pulsação vai ao topo. */
.nds-composer-voice-level {
  --nds-voice-level: 0.62;
}

