withLevelCode.web:
// The component does NOT capture audio. Asking permission, capturing,
// transcribing and what to do with the text belong to whoever consumes it;
// here only the incoming state is drawn.

// The level is DECORATIVE: a number from 0 to 1 that draws the sound and is
// never announced.
{ state: 'recording', level: 0.62, elapsed: '0:12' }

// Capture has stopped and processing has not. The toggle goes disabled, and
// the reason goes into the state text — never into the grey of the button.
{ state: 'transcribing', elapsed: '0:34' }

extensibilityCode.web:
// The component draws what it RECEIVES, and does not know where the sound
// comes from. Permission, capture, transcription and the text's destination
// belong to whoever consumes it.
{
  state: 'recording',  // where dictation stands
  level: 0.62,         // the sound coming in, 0 to 1 — drawing, and only that
  elapsed: '0:12',     // already written: duration format is a language call
  disabled: false,     // dictating is not available now
}

// The request arrives as an intent, not as a new state: between asking to
// start and actually capturing there is a permission only the consumer settles.
onToggle: (intent) => (intent === 'start' ? comecar() : parar());

customizationCode.web:
.nds-composer-voice-status {
  min-inline-size: 8ch;
}

/* The level is a RUNTIME value, which is why it enters as a custom property
   instead of a design `style` — that would leave the theme, the density and
   the type scale behind. With no level declared, the pulse goes to the top. */
.nds-composer-voice-level {
  --nds-voice-level: 0.62;
}

